Object.assign(window.I18N.uk.t,{twin_t:'Це ваш другий акаунт на цьому телефоні',twin_d:'Правило гри: один телефон — одні нагороди. Тут можна грати, але без нагород: Попіл не нараховується, недоступні реклама за нагороду, клан, ринок, арена, рейтинги й вивід коштів. Усе це — лише на першому акаунті цього телефона. Якщо це помилка (це не ваш другий акаунт) — напишіть @Grimtalebot.',twin_ad:'На другому акаунті телефона реклама нагород не дає',acc_banned:'Акаунт заблоковано за порушення правил гри. Якщо вважаєте це помилкою — напишіть у @Grimtalebot.',ban_multi:'Причина: з одного телефона грали кілька акаунтів, і нагороди з них зводились на один. Це порушує правило «один телефон — одні нагороди».'});
