Object.assign(window.I18N.uk.t,{rules_t:'Правила гри',rule_1:'<b>Повага до гравців.</b> Образи, погрози й цькування в чатах — тиша або бан.',rule_2:'<b>Один гравець — один акаунт з нагородами.</b> Другий акаунт з того самого телефона грає без нагород: Попіл не нараховується, недоступні реклама за нагороду, клан, ринок, арена, рейтинги й вивід.',rule_3:'<b>Ферми акаунтів заборонені</b> — блокування всіх причетних акаунтів.',rule_4:'Продаж акаунтів, речей і валюти гри за реальні гроші — заборонено.',rule_5:'Знайшов помилку чи дірку — напиши адміну в @Grimtalebot, а не користуйся нею. Чесних знахідників нагороджуємо.',rule_6:'Без спаму й сторонньої реклами. Посилання — лише на кланові групи Grimtale.',rule_7:'Рішення адміністрації — остаточні.'});
